import{_ as s,a0 as i,w as l,s as p,ao as d,I as r,x as t,a1 as n,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"5 種預防開源許可違規的方法 | LCTT x X-CMD","titleTemplate":false,"description":"5 種預防開源許可違規的方法 | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"5 種預防開源許可違規的方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"5 種預防開源許可違規的方法 | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20220819 5 Ways To Prevent Open Source Licensing Violations","title":"5 種預防開源許可違規的方法","tag":"202306","desc":""},"relativePath":"202306/20220819 5 Ways To Prevent Open Source Licensing Violations.md","filePath":"[post].md"}'),m={name:"202306/20220819 5 Ways To Prevent Open Source Licensing Violations.md"};function u(f,e,h,T,_,x){const a=i("Link");return l(),p("div",null,[e[13]||(e[13]=d('<h1 id="_5-種預防開源許可違規的方法" tabindex="-1">5 種預防開源許可違規的方法 <a class="header-anchor" href="#_5-種預防開源許可違規的方法" aria-label="Permalink to “5 種預防開源許可違規的方法”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202306/26/182415zqdgqmmwlt2qn7zu.jpg" alt=""></p><p>開發人員可以通過將開源軟件集成到其代碼庫中，節省時間並避免重複發明輪子。然而，這也帶來了嚴重的許可侵權風險。你必須遵守適用於重新使用的開源代碼的眾多開源許可證之一。如果你不這樣做，你（或你所在公司）有可能因違反開源許可證條款而被起訴。即使這種訴訟並不普遍發生，它們確實存在。實際上，考慮到現在許多開源項目由希望保護其在開源社區中的投資的企業運營，這種情況在未來可能更加頻繁發生。</p><h3 id="_1、熟悉開源許可證" tabindex="-1">1、熟悉開源許可證 <a class="header-anchor" href="#_1、熟悉開源許可證" aria-label="Permalink to “1、熟悉開源許可證”">​</a></h3><p>瞭解開源許可證是防止開源許可侵權問題中最重要的一步。很容易認為所有開源許可證都施加相同的條件，或者它們都基本要求源代碼的持續可用性。實際上，有數十種不同的開源許可證，它們都有着非常不同的條款。簡單地認為只要你從一個開源項目獲取代碼，你可以隨意使用它並保持源代碼可訪問，這是一個嚴重的錯誤。幾個開源許可證的一個典型但經常被忽視的條件可能是需要向原始作者提供致謝。</p><h3 id="_2、記錄你使用的開源內容" tabindex="-1">2、記錄你使用的開源內容 <a class="header-anchor" href="#_2、記錄你使用的開源內容" aria-label="Permalink to “2、記錄你使用的開源內容”">​</a></h3><p>建立一個標準化的方法來記錄你使用開源代碼的情況是一個優秀的做法。導入模組或從 GitHub 粘貼代碼並不難。但如果你不追蹤代碼來自何處以及使用了何種許可證，你可能會忘記在代碼庫中如何以及在哪裏集成開源內容。此外，如果你在借用代碼時無法證明自己遵守了有效的許可條件，那麼在開源許可證發生變化時可能會產生問題。考慮在文檔維基（如果有的話）中添加一個頁面，列出你使用的開源代碼，以避免出現這個問題。每當你包含開源組件或依賴時，至少在你自己的源代碼中添加註釋。</p><h3 id="_3、避免使用未經授權的開源組件" tabindex="-1">3、避免使用未經授權的開源組件 <a class="header-anchor" href="#_3、避免使用未經授權的開源組件" aria-label="Permalink to “3、避免使用未經授權的開源組件”">​</a></h3><p>有時，你可能會偶然發現一個隱藏的 GitHub 存儲庫或其他源代碼託管位置，其中包含你希望使用的代碼，但沒有提到任何許可指南。你可能會認為代碼的創建者希望讓其成為開源代碼，並且你可以根據自己的意願使用它。但這是一個危險的假設。開發人員可能會後續對代碼設置特定的許可條件，並要求你遵守這些條件，這可能導致未來產生許可侵權的指控。除非你有非常充分的理由，否則避免使用缺乏明確許可限制的模糊代碼。</p><h3 id="_4、創建自己的開源代碼" tabindex="-1">4、創建自己的開源代碼 <a class="header-anchor" href="#_4、創建自己的開源代碼" aria-label="Permalink to “4、創建自己的開源代碼”">​</a></h3><p>將你自己的軟件完全開源是減少與開源許可相關風險的一種方法。這意味着你將自動遵守任何要求保留派生源代碼的開源許可條件。然而，請記住，僅僅開放你自己的代碼並不能確保完全遵守許可證。你仍然需要努力確保你遵守每個許可證的規定，因為適用於你借用的代碼的許可證可能與你選擇的開源許可證不同。然而，你無需擔心與源代碼共享相關的任何條款。</p><h3 id="_5、自動檢測開源組件" tabindex="-1">5、自動檢測開源組件 <a class="header-anchor" href="#_5、自動檢測開源組件" aria-label="Permalink to “5、自動檢測開源組件”">​</a></h3><p>雖然在代碼庫內手動跟蹤你如何使用開源是很好的做法，但通過使用能夠自動識別開源組件和依賴項的軟件，你可以降低出錯的可能性。在這裏，我們應該考慮兩種不同類型的工具。一種是源代碼組成分析（SCA）軟件，它會自動掃描源代碼並識別從值得信任的外部來源獲取的元素。另一種是軟件供應鏈管理解決方案，除其他功能外，還支持查找和監控應用程序堆棧中的任何開源依賴項。</p><p><em>（題圖：MJ/2168d466-cfc3-47de-a8a5-fc7ebaaa445f）</em></p><hr>',15)),r("p",null,[e[1]||(e[1]=t("via: ",-1)),n(a,{href:"https://www.opensourceforu.com/2022/08/5-ways-to-prevent-open-source-licensing-violations/"},{default:o(()=>[...e[0]||(e[0]=[t("https://www.opensourceforu.com/2022/08/5-ways-to-prevent-open-source-licensing-violations/",-1)])]),_:1})]),r("p",null,[e[5]||(e[5]=t("作者：",-1)),n(a,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:o(()=>[...e[2]||(e[2]=[t("Laveesh Kocher",-1)])]),_:1}),e[6]||(e[6]=t(" 選題：",-1)),n(a,{href:"https://github.com/lkxed"},{default:o(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[7]||(e[7]=t(" 譯者：ChatGPT 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:o(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),r("p",null,[e[10]||(e[10]=t("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:o(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const w=s(m,[["render",u]]);export{C as __pageData,w as default};
